/* Import and variation sandbox. Input is always data, never executable content. */
let variationOrigin=null,variationEditing=false;
function snapshotDesk(){return JSON.parse(JSON.stringify({s,history,moves,last,flipped,mode,game,reviewIndex,archiveInfo,localArchiveId,botLevel,botSide,tags:studyTags()}))}
function updateWorkbench(){const branch=variationEditing&&mode==='analysis';$('variation-bar').hidden=!variationOrigin;$('variation-label').textContent=branch?'Пробуем свой вариант. Исходная партия сохранена.':'Можно вернуться к исходной партии.';$('make-variation').disabled=busy||botThinking||!!active();$('train-position').disabled=busy||botThinking||!!active();$('make-variation').textContent=branch?'Новый вариант отсюда':'Вариант на доске';if(branch){$('status').textContent=reviewIndex!==null?'Просмотр вашего варианта. Вернитесь к последнему ходу, чтобы продолжить.':end(s,history)||(s.turn==='w'?'Ход белых в вашем варианте':'Ход чёрных в вашем варианте');$('undo').disabled=!history.length;$('queue-note').textContent='Двигайте фигуры за обе стороны · исходная запись остаётся целой.'}const positionOnly=!currentLine().records.length&&ChessNotation.fen(currentLine().positions[0])!==ChessNotation.fen(initial());if(positionOnly){$('save-game').disabled=false;$('export-pgn').disabled=false}}
async function startVariation(){if(active()||busy||botThinking)return;const position=JSON.parse(JSON.stringify(shownState())),origin=variationOrigin||snapshotDesk();await changeMode('analysis');variationOrigin=origin;variationEditing=true;s=position;history=[];moves=[];last=[];reviewIndex=null;selected=-1;archiveInfo={white:origin.tags.White,black:origin.tags.Black,result:'*',created:Date.now()};localArchiveId=null;lineCache=null;render()}
function returnOriginal(){if(busy)return toast('Дождитесь подтверждения хода.');if(!variationOrigin)return;stopStudy();boardView?.cancel();networkEpoch++;const d=variationOrigin;variationOrigin=null;variationEditing=false;mode=d.mode;localStorage.setItem('dc-mode',mode);s=d.s;history=d.history;moves=d.moves;last=d.last;flipped=d.flipped;game=d.game;reviewIndex=d.reviewIndex;archiveInfo=d.archiveInfo;localArchiveId=d.localArchiveId;botLevel=d.botLevel;botSide=d.botSide;selected=-1;lineCache=null;render();if(mode==='computer')scheduleBot()}
async function trainFromPosition(){if(active()||busy||botThinking)return;if(end(shownState(),[]))return toast('Выберите позицию, в которой игра ещё продолжается.');const position=JSON.parse(JSON.stringify(shownState())),origin=variationOrigin||snapshotDesk();await changeMode('computer');stopStudy();variationOrigin=origin;variationEditing=false;botSide=position.turn;flipped=botSide==='b';s=position;history=[];moves=[];last=[];reviewIndex=null;selected=-1;localArchiveId=null;archiveInfo={white:botSide==='w'?(user?.username||'Вы'):'DJ Doctor',black:botSide==='b'?(user?.username||'Вы'):'DJ Doctor',result:'*',created:Date.now()};lineCache=null;render()}
async function installImported(line){if(busy)throw Error('Дождитесь подтверждения текущего хода и повторите импорт.');await changeMode('analysis');navigate('/');stopStudy();variationOrigin=null;variationEditing=false;game=null;archiveInfo={white:line.tags.White||'Белые',black:line.tags.Black||'Чёрные',result:line.tags.Result||'*',created:Date.now()};history=line.positions.slice(0,-1);s=line.positions.at(-1);moves=line.sans;last=[];reviewIndex=line.records.length?0:null;selected=-1;flipped=s.turn==='b'&&!line.records.length;localArchiveId=null;lineCache=line;lineHistory=history;lineState=s;render();toast(line.records.length?'Партия загружена. Комментарии и вложенные варианты не импортируются.':'Позиция загружена. Можно разобрать её или сыграть с доктором.')}
function openImport(){let format='pgn';show('Принесите свою партию.',`<p>Вставьте PGN для разбора партии или FEN для одной позиции.</p><div class="import-tabs"><button id="import-pgn" class="selected">Партия PGN</button><button id="import-fen">Позиция FEN</button></div><form id="import-form"><label for="import-text" id="import-label">Запись партии PGN</label><textarea id="import-text" class="notation-input" maxlength="131072" spellcheck="false" required placeholder="1. e4 e5 2. Nf3 Nc6 *"></textarea><p class="import-help" id="import-help">Одна партия, до 400 полуходов. Загружается основная линия; комментарии и вложенные варианты пропускаются.</p><label class="pgn-file-label" for="pgn-file">Или выберите файл .pgn</label><input id="pgn-file" type="file" accept=".pgn,text/plain,application/x-chess-pgn"><div class="form-error" id="import-error" role="alert"></div><button class="primary" id="confirm-import">Открыть на доске →</button></form>`);
 const choose=f=>{format=f;const fen=f==='fen';$('import-pgn').classList.toggle('selected',!fen);$('import-fen').classList.toggle('selected',fen);$('import-label').textContent=fen?'Позиция FEN':'Запись партии PGN';$('import-text').placeholder=fen?'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1':'1. e4 e5 2. Nf3 Nc6 *';$('import-help').textContent=fen?'Шесть полей FEN: фигуры, очередь хода, рокировки, взятие на проходе и счётчики.':'Одна партия, до 400 полуходов. Комментарии и вложенные варианты пропускаются.';$('import-error').textContent=''};
 $('import-pgn').onclick=()=>choose('pgn');$('import-fen').onclick=()=>choose('fen');$('pgn-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>131072){$('import-error').textContent='Размер файла должен быть не больше 128 КБ.';return}try{choose('pgn');$('import-text').value=await file.text()}catch{$('import-error').textContent='Не удалось прочитать файл.'}};
 $('import-form').onsubmit=async e=>{e.preventDefault();$('confirm-import').disabled=true;try{const text=$('import-text').value;let line;if(format==='pgn')line=ChessNotation.fromPGN(text);else{const state=ChessNotation.fromFEN(text);line={positions:[state],sans:[],records:[],tags:{Result:'*',SetUp:'1',FEN:ChessNotation.fen(state)}}}await installImported(line)}catch(error){$('import-error').textContent=error.message}finally{if($('confirm-import'))$('confirm-import').disabled=false}};
}
async function copyFEN(){const fen=ChessNotation.fen(shownState());try{await navigator.clipboard.writeText(fen);toast('FEN текущей позиции скопирован')}catch{show('Текущая позиция FEN',`<label for="fen-output">Скопируйте эту строку</label><textarea readonly id="fen-output" class="notation-input">${escapeHtml(fen)}</textarea>`)}}
function initializeWorkbench(){$('nav-import').onclick=openImport;$('make-variation').onclick=startVariation;$('return-original').onclick=returnOriginal;$('train-position').onclick=trainFromPosition;$('copy-fen').onclick=copyFEN}
